package dev.underthebedrock.command;
import dev.underthebedrock.horror.*;import org.bukkit.ChatColor;import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class EvidenceCommand implements CommandExecutor {
 private final OccurrenceDirector director;public EvidenceCommand(OccurrenceDirector d){director=d;}
 @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p)){sender.sendMessage("This command is for players.");return true;}PlayerHorrorMemory m=director.memory(p.getUniqueId());p.sendMessage(ChatColor.DARK_GRAY+"§lYOUR EVIDENCE");p.sendMessage(ChatColor.GRAY+"Chapter: "+ChatColor.WHITE+StoryChapter.forPlayer(m).name().replace('_',' '));p.sendMessage(ChatColor.GRAY+"Clues: "+ChatColor.WHITE+m.discoveredClueCount()+"/"+ClueDefinition.values().length);for(ClueDefinition c:ClueDefinition.values()){boolean found=m.hasClue(c.id());p.sendMessage((found?ChatColor.GREEN+"✓ ":ChatColor.DARK_GRAY+"• ")+ChatColor.GRAY+c.title());}p.sendMessage(ChatColor.LIGHT_PURPLE+"Lore records: "+ChatColor.WHITE+m.loreCount()+"/7");for(String id:new String[]{"architects","researchers","keepers","witnesses","erased","identity_case","architect_seal"})p.sendMessage((m.hasLore(id)?ChatColor.GREEN+"✓ ":ChatColor.DARK_GRAY+"• ")+ChatColor.GRAY+id.replace('_',' ').toUpperCase());p.sendMessage(ChatColor.LIGHT_PURPLE+"Memory recordings: "+ChatColor.WHITE+m.heardRecordings().size()+"/4");for(String id:new String[]{"first_blueprint","first_contact","removal_attempt","identity_fragment"})p.sendMessage((m.hasRecording(id)?ChatColor.GREEN+"✓ ":ChatColor.DARK_GRAY+"• ")+ChatColor.GRAY+id.replace('_',' ').toUpperCase());return true;}
}